"""Prepare isolated DeepSeek/OpenCode jobs and one explicitly owned server."""
from pathlib import Path
import json
import os
import shutil
import subprocess
import time
import urllib.request

ROOT = Path(__file__).resolve().parents[1]
RUN = ROOT / 'runs/science_v11'
EXE = Path(os.environ['APPDATA']) / 'npm/node_modules/opencode-ai/bin/opencode.exe'
COMMON = '''You are a full OpenCode build agent using the user-requested DeepSeek4.1Flash model. Work ONLY in your own directory. Do not ask questions. Use webfetch/websearch/bash/edit normally. No external_directory access. Source snapshot lives in src/musicmix and tests; context/ holds prior research, source manifests, and feedback. Do not modify context. Prefer official existing code/pretrained models; do not reconstruct a published model with substitute features. Do not train on or tune thresholds to user feedback. V8/V10 user judgments are frozen diagnostic holdouts. No claims of 10/10, SOTA, calibrated confidence, resolution from RMS drop, or boundary label as certified phrase completion. Missing evidence stays unknown. Write a short REPORT.md with exact commands/tests, limitations and source URLs. Research claims must separate measured evidence, theoretical proposal, and engineering hypothesis. Downloads: official/publisher/author open material only; no pirate books. Save permitted original PDF/HTML and extracted text, bibliographic metadata/URL/SHA256/access/read-depth. Paywall=metadata/abstract only, never fulltext claim. Science-backed means faithfully reuse papers AND validate real code, not invent thresholds and cite a paper. No global installs, no new heavy model runs unless your task specifically allows them. Use pyproject testpaths, PYTHONPATH=src. Tests should target failures/invariants rather than mirror implementation. Files in your owned task list only; root integrates changes later. Finish practical work before REPORT, do not just plan. You have 30min.
'''
JOBS = {
 'psychology_library': '''Collect and actually archive at least five core primary papers on musical expectancy/tension/multiscale memory/EDM preparation and arrivals. Start with LehneKoelsch2015 doi10.3389/fpsyg.2015.00079, Farbood2012 authorPDF https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/f/11865/files/2020/08/Farbood_2012_Musical_Tension.pdf , Turrell2025 https://kar.kent.ac.uk/106400/ , Grosz2025 doi10.1177/10298649251321709 and newer relevant replications. Use pypdf or pdftotext for PDFs. Own research/01_psicologia_aspettativa/ originals/ texts/ sources.json and RIASSUNTO.md, plus research/00_metodo/RIASSUNTO.md. Summaries Italian, citations with pages/sections, domain transfer limits, testable design for change/stay/continue/arrive. Mark actual read depth. Do not claim a universal mix psychology law. Reuse context/research previous work and correct errors. No product code.''',
 'hiphop_phrase': '''Research and archive primary material on hip-hop phrase, flow/prosody, pickups, enjambment, vocal phrase completion. Adams2020 https://mtosmt.org/issues/mto.20.26.2/mto.20.26.2.adams.html plus MCFlow/Ohriner/Duinker public thesis/papers. Own research/02_fraseggio_rap_voce/{originals,texts,sources.json,RIASSUNTO.md}. Additionally implement src/musicmix/phrase_evidence.py and tests/test_phrase_evidence.py: provider-neutral glue consumes existing Whisper segment/word times plus optional learned phrase provider. Distinguish word gap from syntactic closure; never call ASR punctuation a certified phrase. Expose observed end-of-ASR-segment + last/next word clearance, active utterance, pickup/dependency uncertainty, canonical timing. Unknown stays unknown; no new acoustic proxy model. API functions document keyword schemas. No model installs. Ensure JSON-friendly results for root integration. Aim usable analysis around arbitrary cue_sample, sample_rate, duration_samples, not beat-only times.''',
 'joint_decision': '''Implement src/musicmix/transition_intent.py and tests/test_transition_intent.py. Read existing trajectory.py, expectation.py and V9 event spec. This is action selection glue, not a new learned tension model. Provide explicit actions stay/prepare/execute/defer and intents preserve_groove/continue_motion/arrive/deliberate_contrast. Consume A_before, A_natural_after, B_before, B_after existing trajectory profiles plus provided phrase/functional section evidence; use analyze_expectation where possible, keeping labels honest. Frame cross-song vs natural-A counterfactual without assuming same-recording is always better. Must distinguish local phrase completion from ongoing global motion; high→high can be continuation without release, low→low can preserve groove, low→low is not automatic interruption. Arrive requires supported multi-domain event evidence, not merely section label/quiet intro. Missing provider cannot become zero/confident reject. Expose evidence and deterministic rankable utility separately from calibrated probability (none). No fitting to V10 or magic thresholds justified by fake paper claims; version any inherited heuristic policy and mark unvalidated. Tests for open-phrase exit, continued motion, neutral compatible groove, arbitrary section label, unknown, source identity shortcut. Italian design research/03_struttura_transizioni_dj/RIASSUNTO.md plus sources manifest from primary papers/books official excerpts. Only own two source/test files and own research folder.''',
 'intent_renderer': '''Implement src/musicmix/intent_render.py and tests/test_intent_render.py, reusing musical_preview.py and blend_preview.py where appropriate and FFmpeg filters if beneficial. Goal production-safe event render: explicit source/out clocks, context >=16s each side configurable, optional incoming pickup vs arrival distinction, exclusive output, SHA metadata. Add bounded local level matching (attenuation preferred to boost, never near-silence amplification; preserve ramps and no clipping); report original and resulting gains/levels. Offer handoff and existing equal-power overlap only when overlap_vocal_safety explicitly confirms safe vocal overlap AND tempos acceptable; unknown/occupied denies blend. Do not silently time-stretch/drop words; no fabricated beat grids, no new ML. Keep original anchor_handoff_v1 behavior untouched. Prefer add wrapper around existing code rather than duplicate. Tests actual PCM anchor alignment, dangerous silence, source identity, overlap unknown, clipping, sample-rate mismatch. Research own research/05_renderer_loudness_tempo/{RIASSUNTO.md,sources.json}, official primary EBU/ITU loudness guidance and mixing source literature only; distinguish loudness matching from tension. No heavy installs.''',
 'feedback_validator': '''Implement src/musicmix/transition_validation.py and tests/test_transition_validation.py. Independent automatic verification for rendered transition events, reuse mix_quality.py and existing vocal/trajectory contracts. Hard defects (identity/audio hash, invalid mapping/out-of-bounds, nonfinite/clipping, known vocal overlap/cut, mismatched tested anchors) separate from descriptive level change, phrase unknown, uncertain motion. Do not convert 12dB jump into bad music or SongEval Coherence into acceptance; user-approved clip003 had a large level jump. Expose eligible_for_review vs musically_validated (unknown), risk/coverage, component reasons. Counterfactual/synthetic perturbation benchmark helper: order swaps, early/late shifts, silence/clipping perturbations are known construction properties, NOT universal bad taste. Keep holdout user judgments separate, no adaptive reward tuning. Provide rank-stability/coverage diagnostic usable by root. Research archive own research/06_valutazione_autofeedback with core papers on music evaluation/reward hacking/proper validation, sources.json, RIASSUNTO.md. No heavy ML or global installs.''',
 'benchmark_data': '''Acquire and inspect REAL publicly available metadata/annotations (not large audio) for DJ transition timing, phrase/section structure and preference evaluation. Prioritize Raveform official datasets and DJ transition annotations; Harmonix functional sections; SALAMI metadata if relevant. Pin source revisions/licenses, distinguish estimated alignments vs expert labels and audio rights; train/test leakage across same recordings/artists. Save own research/07_dati_benchmark/{originals,texts,sources.json,RIASSUNTO.md,download_manifest.json}. Max100MB. Must actually download and parse at least one useful annotation source, report counts/schema and limitations. Build tools/inspect_transition_benchmark.py (self-contained parser no fake fixtures presented as real data) if useful, output real dataset statistics. Root will incorporate this into external validation gates. No model installs/source edits outside owned files.''',
 'tension_model': '''Try faithfully reuse official TenseMusic https://github.com/vivienbarchet/TenseMusic (Barchet2024 doi10.1371/journal.pone.0296385). Read actual source/checkpoint/features dependencies, pin commit, archive paper/text and licenses in research/04_modelli_preaddestrati/. Own tools/run_tensemusic_pilot.py (if feasible), runtime/ (isolated installs only), outputs/, research/04_modelli_preaddestrati/{RIASSUNTO.md,sources.json,originals,texts}. You have context/audio_pilot.wav canonical audio and its matching structure/vocals. Max400MB new downloads, no global TensorFlow/Torch. Check actual full architecture, no replacement FFT/RMS implementation masquerading as TenseMusic. ONNX BasicPitch official if supported is allowed; unavailable dependencies must be honestly reported. Goal actual one clip official end-to-end run if feasible; otherwise exact runnable feature-level official model example and blocker, NOT invented inference. Limit CPU threads1, no repeated giant installs. Archive source and command provenance. Do not modify host/WSL, opencode server or other jobs. Root decides adoption after outputs.''',
 'pretrained_critic_research': '''Targeted primary-source research for EXISTING pretrained audio models that can evaluate phrase completion, energy/motion trajectory and cross-song musical coherence (not just full-song aesthetics). Inspect official code/weights MusicFlamingo, music understanding models, tension datasets, MuQ representations, published mix evaluation. Existing project already has MuQ/SongEval/CUE-DETR/LinkSeg, no need repeat those wrappers. No model weights downloads or heavy runtime. Archive up to5 pertinent public primary papers/repos texts with source metadata in research/06_valutazione_autofeedback_modelli/. Produce RIASSUNTO.md and ADOPTION.json with real input/task/domain/CPU-memory/download/weight availability/license and actual reuse paths vs limitations. Do not claim audio LLM opinion is validated objective reward or absence of annotations is negative. Need concrete feasibility shortlist and recommendation for available CPU, no invented model architecture or retraining.'''
}

def main():
    if RUN.exists():
        raise FileExistsError('Preserve existing swarm; inspect/resume instead')
    server_dir = RUN / 'server'
    server_dir.mkdir(parents=True)
    jobs = []
    for name, task in JOBS.items():
        folder = RUN / 'agents' / name
        folder.mkdir(parents=True)
        shutil.copytree(ROOT/'src', folder/'src', ignore=shutil.ignore_patterns('__pycache__'))
        shutil.copytree(ROOT/'tests', folder/'tests', ignore=shutil.ignore_patterns('__pycache__'))
        shutil.copy2(ROOT/'pyproject.toml', folder/'pyproject.toml')
        context = folder/'context';context.mkdir()
        shutil.copytree(ROOT/'ricerca/v9',context/'research',ignore=shutil.ignore_patterns('__pycache__'))
        for path in ('ricerca/MOTION_SUSPENSE_RICERCA.md','ricerca/v8/PSYCHOLOGY_V8.md','docs/history/23_MODELLI_PREADDESTRATI_V10.md','runs/pretrained_v10/ROOT_STATUS.json','runs/pretrained_v10/functional_context_audit.json'):
            shutil.copy2(ROOT/path,context/Path(path).name)
        shutil.copy2(ROOT.parent/'giudizi json/feedback_verbale_V10_review_8_audio.json',context/'user_feedback_V10_holdout.json')
        (folder/'TASK.md').write_text(COMMON+'\nYOUR TASK:\n'+task,encoding='utf-8')
        jobs.append({'name':name,'directory':str(folder.resolve()),'status':'pending'})
    # One small, exact canonical audio copy for the optional official model pilot.
    audio = ROOT/'runs/reminder_to_too_many_nights/audio/a.wav'
    destination = RUN/'agents/tension_model/context/audio_pilot.wav'
    shutil.copy2(audio,destination)
    shutil.copy2(ROOT/'runs/structure_v2/a.json',destination.parent/'structure.json')
    shutil.copy2(ROOT/'runs/vocals_v2/a.json',destination.parent/'vocals.json')
    config={'permission':{'edit':'allow','bash':'allow','webfetch':'allow','websearch':'allow','external_directory':'deny','question':'deny'},'provider':{'opencode':{'options':{'apiKey':'public'}}}}
    env=dict(os.environ,OPENCODE_CONFIG_CONTENT=json.dumps(config))
    with (server_dir/'server.log').open('ab') as log:
        server=subprocess.Popen([str(EXE),'serve','--port','4096','--hostname','127.0.0.1'],cwd=server_dir,env=env,stdout=log,stderr=log,creationflags=subprocess.CREATE_NO_WINDOW)
    (server_dir/'pid.txt').write_text(str(server.pid))
    manifest={'schema_version':'musicmix.science-swarm.v11','date':'2026-10-20','server_executable':str(EXE),'jobs':jobs,'model_requested':'opencode/deepseek-v4.1-flash-free','task_scope':'maintained research library plus executable psychologically informed transition pipeline'}
    (RUN/'swarm.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    for _ in range(30):
        try:
            with urllib.request.urlopen('http://127.0.0.1:4096/global/health',timeout=2) as response:
                health=json.load(response)
            if health.get('healthy'):
                print(json.dumps({'status':'ready','server_pid':server.pid,'health':health,'jobs':len(jobs)}),flush=True)
                return
        except Exception:
            time.sleep(.5)
    raise RuntimeError('Server failed health check; inspect owned server log')

if __name__=='__main__':
    main()
